/// and can fail the next call definitely. All coordination uses condvars, no
/// sleeps, and no network.
#[derive(Default)]
pub struct FakeArchiveProvider {
    inner: Arc<FakeInner>,
}

#[derive(Debug, Clone, Copy, Default)]
struct FakeState {
    paused: bool,
    fail_next: bool,

